/* Bounded sweep: only ref-named expired/unparsable tickets and our own stale .new-* and .claim-* temps are unlinked; foreign names are never touched. */
function sweepTerminalTickets(directory, now) { let names = []; try { names = fs.readdirSync(directory).slice(0, TERMINAL_SWEEP_LIMIT); } catch { return; } for (const name of names) { try { if (name.charAt(0) === ".") { const temp = /^\.(?:new-[0-9a-f]{32}|claim-[0-9a-f]{32}-[1-9][0-9]{0,9})$/.test(name); if (temp === false) continue; const tempStats = fs.lstatSync(directory + "/" + name); if (tempStats.isFile() !== true || tempStats.isSymbolicLink() === true || now - tempStats.mtimeMs < TERMINAL_TICKET_TTL) continue; fs.unlinkSync(directory + "/" + name); continue; } if (TERMINAL_TICKET_REF.test(name) === false) continue; const stats = fs.lstatSync(directory + "/" + name); if (stats.isFile() !== true || stats.isSymbolicLink() === true) continue; const raw = fs.readFileSync(directory + "/" + name, "utf8"); if (raw.length > TERMINAL_TICKET_MAX_BYTES) { fs.unlinkSync(directory + "/" + name); continue; } const value = JSON.parse(raw); if (isRecord(value) !== true || Number.isSafeInteger(value.expiresAt) !== true || value.expiresAt <= now) fs.unlinkSync(directory + "/" + name); } catch { try { fs.unlinkSync(directory + "/" + name); } catch {} } } }
